<div class="page-head"><div><p class="section-kicker">Shared customer pipeline</p><h1>Inquiries</h1><p>Track leads from first contact through qualification, quotation, and completion without duplicating an inbox in every industry module.</p></div><span class="badge"><?= number_format($total) ?> total</span></div>
<section class="card"><form class="filter-bar" method="get" action="<?= e_attr($basePath) ?>/admin/inquiries"><input type="hidden" name="p" value="/admin/inquiries"><label>Search<input name="q" value="<?= e_attr($search) ?>" placeholder="Name, email, or subject"></label><label>Status<select name="status"><option value="">All statuses</option><?php foreach($statuses as $option): ?><option value="<?= e_attr($option) ?>" <?= $status===$option?'selected':'' ?>><?= e(ucwords($option)) ?></option><?php endforeach; ?></select></label><button class="btn secondary">Filter</button></form>
<?php if(!$inquiries): ?><div class="empty-state"><strong>No inquiries found</strong><span>New module-created inquiries will appear here.</span></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Subject</th><th>Status</th><th>Priority</th><th>Received</th><th></th></tr></thead><tbody><?php foreach($inquiries as $inquiry): ?><tr><td><strong><?= e($inquiry['customer_name']) ?></strong><br><span class="muted"><?= e($inquiry['customer_email']?:$inquiry['customer_phone']) ?></span></td><td><?= e($inquiry['subject']) ?></td><td><span class="badge"><?= e(ucwords($inquiry['status'])) ?></span></td><td><?= e(ucwords($inquiry['priority'])) ?></td><td><?= e(date('M j, Y g:i a',strtotime($inquiry['created_at']))) ?></td><td><a class="btn small secondary" href="<?= e_attr($basePath) ?>/admin/inquiries/view&id=<?= (int)$inquiry['id'] ?>">Open</a></td></tr><?php endforeach; ?></tbody></table></div><?php $pages=max(1,(int)ceil($total/$perPage));if($pages>1): ?><nav class="pagination" aria-label="Inquiry pages"><?php for($p=1;$p<=$pages;$p++): ?><a class="<?= $p===$page?'active':'' ?>" href="<?= e_attr($basePath) ?>/admin/inquiries&q=<?= rawurlencode($search) ?>&status=<?= rawurlencode($status) ?>&page=<?= $p ?>"><?= $p ?></a><?php endfor; ?></nav><?php endif;endif; ?></section>
